def split_by_reference(sizes, ref):
    lo, i, hi = 0, 0, len(sizes)
    while i < hi:
        x = sizes[i]
        if x < ref:
            sizes[lo], sizes[i] = sizes[i], sizes[lo]
            lo += 1
            i += 1
        elif x > ref:
            hi -= 1
            sizes[i], sizes[hi] = sizes[hi], sizes[i]
        else:
            i += 1
    return (lo, hi)

